codeBackup.css_template:
#{{ID}} .na-zywo-wrapper {
    display: inline-flex;
    flex-direction: column;
    align-items: stretch;
    transform-origin: center center;
    opacity: 0;
    transform: {{ANIMATION_IN_TRANSFORM}};
    transition: all {{ANIMATION_DURATION}}s {{ANIMATION_EASE}};
    box-shadow: {{BOX_SHADOW}};
    border-radius: 4px;
    overflow: hidden;
}
#{{ID}} .na-zywo-container {
    display: inline-flex;
    align-items: center;
    max-width: 820px;
    box-sizing: border-box;
    background: {{PRIMARY_BG}};
    padding: 8px 16px;
    border-radius: 4px;
    font-family: '{{FONT_FAMILY}}', 'Arial', sans-serif;
}
#{{ID}} .na-zywo-dot {
    width: 14px;
    height: 14px;
    background-color: #ffffff;
    border-radius: 50%;
    margin-right: 12px;
    animation: pulse-dot 1s infinite alternate;
    box-shadow: {{BOX_SHADOW}};
}
#{{ID}} .na-zywo-text {
    display: inline-flex;
    max-width: 820px;
    overflow: hidden;
    box-sizing: border-box;
    color: {{TITLE_COLOR}};
    font-size: {{TITLE_SIZE}}px;
    font-weight: {{TITLE_WEIGHT}};
    letter-spacing: 1px;
    text-transform: uppercase;
}
@keyframes pulse-dot {
    0% { opacity: 1; transform: scale(1); }
    100% { opacity: 0.3; transform: scale(0.9); }
}

