elements.js_template:
(() => {
    const root = document.getElementById("{{ID}}");
    if (!root) return;
    const scene = root.querySelector('.cg-scene') || root;
    const layer = n => root.querySelector('.cg-l' + n);
    const motions = [];
    const fitSpec = {"frameW":206,"auto":[{"n":3,"x":42,"w":148,"align":"left","minW":null,"maxW":900}],"layers":[{"n":1,"to":3,"mode":"size","x":0,"w":206}]};
    const fitRun = () => {
        if (!root.isConnected) return;
        const dl = {}; let grow = null;
        fitSpec.auto.forEach(a => {
            const cl = layer(a.n), t = cl && cl.querySelector('.cg-t');
            if (!t) return;
            const pw = t.style.getPropertyValue('width'), pp = t.style.getPropertyPriority('width');
            const pf = t.style.getPropertyValue('flex'), pfp = t.style.getPropertyPriority('flex');
            t.style.setProperty('width', 'max-content', 'important'); t.style.setProperty('flex', 'none', 'important');
            const nat = t.offsetWidth;
            if (pw) t.style.setProperty('width', pw, pp); else t.style.removeProperty('width');
            if (pf) t.style.setProperty('flex', pf, pfp); else t.style.removeProperty('flex');
            if (!(nat > 0)) return;
            let W = nat;
            if (a.minW !== null) W = Math.max(W, a.minW);
            if (a.maxW !== null) W = Math.min(W, a.maxW);
            const d = W - a.w, sh = a.align === 'right' ? -d : a.align === 'center' ? -d / 2 : 0;
            dl[a.n] = { d, sh };
            cl.style.width = W + 'px'; cl.style.left = (a.x + sh) + 'px';
            grow = grow === null ? d + sh : Math.max(grow, d + sh);
        });
        fitSpec.layers.forEach(f => {
            const cl = layer(f.n), k = dl[f.to];
            if (!cl || !k) return;
            if (f.mode === 'follow') cl.style.left = (f.x + k.d + k.sh) + 'px';
            else { cl.style.width = (f.w + k.d) + 'px'; cl.style.left = (f.x + k.sh) + 'px'; }
        });
        if (grow !== null) scene.style.width = (fitSpec.frameW + grow) + 'px';
    };
    fitRun();
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fitRun);
    const textNs = [3];
    const motionOf = n => motions.find(m => m.n === n) || {};
    const on = c => c && c.type && c.type !== 'none';
    CGMotion.mount(root, {
        container: scene,
        animIn: {{{ANIMATION_IN_JSON}}}, animOut: {{{ANIMATION_OUT_JSON}}},
        text: { type: 'none' }, textOut: { type: 'none' },
        loop: {{{LOOP_JSON}}},
        onShow(tl) {
            const T = {{{TEXT_ANIM_JSON}}}, TS = {{{TEXT_ANIM_SYNC}}};
            const baseEnd = tl.duration();
            motions.forEach(m => {
                const el = layer(m.n);
                if (el && on(m.in)) tl.add(CGMotion.standardIn(el, m.in), 0);
            });
            textNs.forEach(n => {
                const el = layer(n), own = motionOf(n).text;
                const eff = own || T;
                if (!el || !on(eff)) return;
                const sub = CGMotion.applyTextEffect(el, eff);
                if (sub) tl.add(sub, own ? 0 : (TS ? Math.max(0, baseEnd - 0.1) : 0));
            });
        },
        onHide() {
        }
    });
    // Wyjście: najpierw OUT warstw (i ich efekty tekstu), potem OUT całego elementu z inspektora
    const baseHide = root.__slt_hide;
    root.__slt_hide = () => {
        const TO = {{{TEXT_ANIM_OUT_JSON}}}, TOS = {{{TEXT_ANIM_OUT_SYNC}}};
        const pre = gsap.timeline(), par = gsap.timeline();
        motions.forEach(m => {
            const el = layer(m.n);
            if (el && on(m.out)) pre.add(CGMotion.standardOut(el, m.out), 0);
        });
        textNs.forEach(n => {
            const el = layer(n), own = motionOf(n).textOut;
            const eff = own || TO;
            if (!el || !on(eff)) return;
            const sub = CGMotion.applyTextOutEffect(el, eff);
            if (!sub) return;
            if (own) pre.add(sub, 0); else par.add(sub, 0);
        });
        const base = baseHide();
        const tl = gsap.timeline();
        tl.add(pre);
        if (TOS) { tl.add(par); tl.add(base, '>-0.1'); }
        else { tl.add(base); tl.add(par, '<'); }
        return tl;
    };
})();
